column31:
Guide: Create a csv file with format as attachment > Login with lspitsupport > Run PowerShell with administrator rights > Input LDAP Query as below and run

Import-Module ActiveDirectory -- Import Active directory into Powershell

$users = Import-Csv -Path "F:\Ticket17959.csv" -- create a variable "users" to hold context in file .csv -Path "[your local file path]"
foreach ($user in $users) {    ---- Create a loop through each user in file .csv
 if ($user.SamAccountName -and $user.Title) {  
 try {
 Set-ADUser -Identity $user.SamAccountName -Title $user.Title   - search for user identity and replace user job title by column name Title in csv file. If column name " ABC " then correct syntax will be like this : -Title $users.ABC
 Write-Host "Updated $($user.SamAccountName): $($user.Title)" -ForegroundColor Green  --- Force powershell to write success results in green color
 } catch {
 Write-Host "Failed to update $($user.SamAccountName): $_" -ForegroundColor Red  -----Force powershell to write failed results in green red
 }
 }
}

